  mk(new T3.BoxGeometry(3,3.4,1.4),dark,-3.3,-1.1,2,B.torso);mk(new T3.BoxGeometry(.8,.35,.15),m3('#d78a51'),-3.3,-.8,2.8,B.torso);
  mk(new T3.BoxGeometry(1.2,1.9,.3),silver,0,-.1,.8,B.handL).rotation.x=-.5;
